import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.7nMnW4XS.js";const p=JSON.parse('{"title":"ADR-069 — Three-layer overlay-completeness policy (validate-data check + opt-in smoke pre-push + AGENTS.md rule)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-069.md","filePath":"adr/ADR-069.md"}'),i={name:"adr/ADR-069.md"};function n(r,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-069-—-three-layer-overlay-completeness-policy-validate-data-check-opt-in-smoke-pre-push-agents-md-rule" tabindex="-1">ADR-069 — Three-layer overlay-completeness policy (validate-data check + opt-in smoke pre-push + AGENTS.md rule) <a class="header-anchor" href="#adr-069-—-three-layer-overlay-completeness-policy-validate-data-check-opt-in-smoke-pre-push-agents-md-rule" aria-label="Permalink to &quot;ADR-069 — Three-layer overlay-completeness policy (validate-data check + opt-in smoke pre-push + AGENTS.md rule)&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-05-25 Closes into · AGENTS.md §&quot;Data layer rules&quot; (overlay-completeness rule + history note) Related ADRs · ADR-046 (image-provenance validator), ADR-051 (link-provenance validator), ADR-052 (symmetric fleet ↔ mission link validator) Triggered by · GH #83 e2e regression (May 2026)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>GH #83 (&quot;unpack better satellite orbits on Earth and support in science&quot;) shipped on 2026-05-24 across two commits — <code>27eec78e7</code> (en-US infra + 11 new constellation entries in <code>static/data/earth-objects.json</code>) and <code>e84ada626</code> (13-locale translations). Local preflight passed, pre-push hook passed, CI on the head commit reported green for <code>CI</code> and <code>docker-e2e</code>&#39;s build stage. Then <code>e2e</code> (Playwright suite, runs on push-to-main) turned red with eleven runtime SvelteKit 404s:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WebServer] SvelteKitError: Not found: /data/i18n/en-US/earth-objects/starlink.json</span></span>\n<span class="line"><span>[WebServer] SvelteKitError: Not found: /data/i18n/en-US/earth-objects/oneweb.json</span></span>\n<span class="line"><span>... (9 more)</span></span></code></pre></div><p>The defect: when adding a new ID to <code>earth-objects.json</code>, the contributor must also create the matching i18n overlay at <code>static/data/i18n/en-US/earth-objects/&lt;id&gt;.json</code>. The base file declares the record; the overlay supplies the localised <code>name</code> / <code>short</code> / <code>description</code> / <code>scale_fact</code>. Without the overlay, <code>/earth</code> route hydration 404s on first paint when the user views the marker detail panel. Eleven such overlays were missing because the work focused on the base registry, the schema, and the translation pipeline — none of which require the en-US overlay to be present.</p><p>This same defect class affects <strong>five other registries</strong> that follow the same base + overlay shape: <code>static/data/fleet/index.json</code>, <code>static/data/moon-sites.json</code>, <code>static/data/mars-sites.json</code>, <code>static/data/science/&lt;tab&gt;/_index.json</code> (both base file and overlay), and the multi-file <code>iss-modules</code> / <code>tiangong-modules</code> / <code>iss-visitors</code> / <code>tiangong-visitors</code> overlays. An audit at the time of this ADR found 18 orphan IDs across the project — 15 in the just-shipped #83 work and 3 in concurrent parallel-agent work (luna16 / luna21 / beresheet, added to moon-sites.json by the moon-tier3 batch but never given overlays).</p><p>The existing safety nets:</p><ul><li><strong><code>typecheck</code></strong> type-checks TypeScript + Svelte source but never reads runtime JSON data.</li><li><strong><code>lint</code></strong> style-checks code but never walks <code>static/data/</code>.</li><li><strong><code>test</code></strong> unit-tests individual modules but no test enumerates the per-registry overlay coverage.</li><li><strong><code>validate-data</code></strong> runs AJV schemas + provenance + symmetric-link checks but had no overlay-completeness check — its mental model was &quot;is each individual file well-formed&quot;, not &quot;does the cross-reference graph between registries close&quot;.</li><li><strong><code>build</code></strong> (SvelteKit adapter-static) compiles the route output but the missing overlays only 404 at <em>runtime</em> when the <code>/earth</code> panel actually requests them, not at build time.</li><li><strong><code>e2e</code></strong> (Playwright) catches the regression at the right moment but runs only on CI push-to-main, not pre-push.</li></ul><p>The asymmetry: the preflight chain that the pre-push hook runs costs ~3 minutes on a developer laptop, the e2e chain costs ~16 minutes and is gated to CI. Most of the time this is the right trade. For the specific defect class of &quot;missing overlay file&quot; it&#39;s the wrong one — the regression is determinate and cheap to detect locally if you look for it specifically, but expensive to detect by running every Playwright spec.</p><p>The decision: <strong>close the specific gap with cheap, targeted local-only enforcement, layered so that the catching net is graded by certainty + cost.</strong></p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>A three-layer policy enforces overlay-completeness at increasing scope + cost, layered from cheapest-always-on to most-thorough-opt-in.</strong></p><h3 id="layer-1-—-validate-data-overlay-completeness-check-always-on" tabindex="-1">Layer 1 — <code>validate-data</code> overlay-completeness check (always-on) <a class="header-anchor" href="#layer-1-—-validate-data-overlay-completeness-check-always-on" aria-label="Permalink to &quot;Layer 1 — `validate-data` overlay-completeness check (always-on)&quot;">​</a></h3><p><code>scripts/validate-data.ts</code> gains a new validation stage that runs after image-pipeline-manifest validation and before process-exit. For each of the registries below it iterates all declared IDs and verifies that the corresponding en-US overlay file exists on disk; missing overlays accumulate into the same <code>overlayFailed</code> counter that participates in the final non-zero-exit gate.</p><table tabindex="0"><thead><tr><th>Base registry</th><th>Overlay path checked</th></tr></thead><tbody><tr><td><code>static/data/earth-objects.json</code> (top-level array, <code>id</code> field)</td><td><code>static/data/i18n/en-US/earth-objects/&lt;id&gt;.json</code></td></tr><tr><td><code>static/data/fleet/index.json</code> (top-level array, <code>id</code> + <code>category</code> fields)</td><td><code>static/data/i18n/en-US/fleet/&lt;category&gt;/&lt;id&gt;.json</code></td></tr><tr><td><code>static/data/moon-sites.json</code> (top-level array, <code>id</code> field)</td><td><code>static/data/i18n/en-US/moon-sites/&lt;id&gt;.json</code></td></tr><tr><td><code>static/data/mars-sites.json</code> (top-level array, <code>id</code> field)</td><td><code>static/data/i18n/en-US/mars-sites/&lt;id&gt;.json</code></td></tr><tr><td><code>static/data/science/&lt;tab&gt;/_index.json</code> (<code>ids</code> array)</td><td>both <code>static/data/science/&lt;tab&gt;/&lt;id&gt;.json</code> (base) AND <code>static/data/i18n/en-US/science/&lt;tab&gt;/&lt;id&gt;.json</code> (overlay)</td></tr></tbody></table><p>Cost on a fresh node tree: ~50 ms total. The check runs inside the existing <code>validate-data</code> invocation, so it participates automatically in the preflight chain (typecheck → lint → test → validate-data → check-no-secrets → build) and therefore in the pre-push hook. No new dependency, no new wiring. Other locales are not checked — the runtime i18n loader falls back to en-US for any missing locale-specific overlay, so en-US presence is the necessary + sufficient guarantee that a runtime 404 won&#39;t occur.</p><h3 id="layer-2-—-opt-in-smoke-subset-e2e-in-pre-push-off-by-default" tabindex="-1">Layer 2 — opt-in smoke-subset e2e in pre-push (off by default) <a class="header-anchor" href="#layer-2-—-opt-in-smoke-subset-e2e-in-pre-push-off-by-default" aria-label="Permalink to &quot;Layer 2 — opt-in smoke-subset e2e in pre-push (off by default)&quot;">​</a></h3><p>A new npm script <code>test:e2e:smoke</code> runs only <code>tests/e2e/landing.spec.ts</code> + <code>tests/e2e/smoke.spec.ts</code> against <code>desktop-chromium</code> with <code>--workers=1</code>. Those two specs are deliberately chosen because they together hit every top-level route once at first paint, which is precisely the moment a missing-overlay 404 surfaces. Cost: 30-60 seconds on a developer laptop after the <code>npm run build</code> that&#39;s already needed for any Playwright run.</p><p><code>.husky/pre-push</code> gains an env-var-gated stage that runs this script after <code>npm run preflight</code> succeeds, only when the contributor sets <code>PREFLIGHT_INCLUDE_SMOKE=1</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PREFLIGHT_INCLUDE_SMOKE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre></div><p>Off by default because (a) daily commits don&#39;t pay the 30-60 second cost on every push, (b) Layer 1 already catches the dominant defect class, and (c) the smoke subset is only meaningful when the working tree changed something route-relevant (earth-objects, fleet data, moon-sites, mars-sites, /earth or /moon or /mars source). Recommended for release-cut pushes and for any push that touches a registry. The env-var gate is documented in <code>.husky/pre-push</code> comments and in AGENTS.md.</p><h3 id="layer-3-—-agents-md-non-negotiable-rule-registry-to-overlay-table" tabindex="-1">Layer 3 — AGENTS.md non-negotiable rule + registry-to-overlay table <a class="header-anchor" href="#layer-3-—-agents-md-non-negotiable-rule-registry-to-overlay-table" aria-label="Permalink to &quot;Layer 3 — AGENTS.md non-negotiable rule + registry-to-overlay table&quot;">​</a></h3><p>A new paragraph under AGENTS.md §&quot;Data layer rules&quot; documents the registry → overlay mapping that every agent (Claude, Cursor, human, future) must respect when adding a new ID. The text is marked <code>NON-NEGOTIABLE</code> (matching the existing image-provenance and link-provenance rules) and includes a history note linking back to GH #83 so future agents understand why the rule exists. Layer 3 doesn&#39;t enforce anything mechanically — Layers 1 + 2 do that — but it surfaces the rule at the moment an agent is most likely to be about to break it (reading AGENTS.md before touching the data layer).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>The exact defect class that caused GH #83 fails at preflight now</strong>, before push, on every developer machine. Layer 1 caught 18 orphan IDs the moment it activated — 15 from the just-shipped #83 work, 3 from concurrent parallel-agent work — and forced them to be backfilled in the same commit that introduced Layer 1.</li><li><strong>The graded design avoids the &quot;preflight is too slow now&quot; trap.</strong> Layer 1 adds 50 ms; daily pushes don&#39;t notice. Layer 2 stays opt-in for cases where the 30-60s is justified. The pre-push hook stays default-cheap.</li><li><strong>The registry-to-overlay contract is now explicit + discoverable</strong>, both in the validator code (single point of truth for the canonical paths) and in AGENTS.md (single point of agent-facing rule).</li><li><strong>No new dependency.</strong> Both Layers 1 + 2 use tooling already in the tree (validate-data, Playwright, husky).</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Layer 1 enforces only en-US overlay presence</strong>, not non-English locale overlays. A non-English translation that&#39;s missing won&#39;t fail validate-data; it will fall back to en-US at runtime. This is the right trade — locale completeness is owned by a separate i18n pipeline, and tying validate-data to it would slow daily preflight unnecessarily — but it means an agent could in principle ship a feature with English-only text where the project expects 14-locale coverage. Mitigation: the translation pipeline has its own audit step that catches this asymmetrically.</li><li><strong>Layer 2 requires the contributor to remember to set the env var.</strong> A push that changes earth-objects.json but doesn&#39;t set <code>PREFLIGHT_INCLUDE_SMOKE=1</code> could still in principle reach origin with a runtime 404 that Layer 1 missed. The mitigation is that Layer 1 already catches the specific overlay-missing class; Layer 2 catches secondary issues (route handler bugs, broken navigation links, etc.) which are a different defect family. In practice the env var is a release-readiness aid, not a daily-push gate.</li><li><strong>18 orphan overlays were scaffolded in the activation commit using generated descriptions.</strong> The fleet/constellation overlays use authored descriptions; the moon-site overlays (luna16 / luna21 / beresheet) use hand-written historical fact entries. Quality is &quot;ship-ready&quot; but not &quot;translator-polished&quot; — the i18n pipeline can refine them later.</li></ul><h3 id="neutral" tabindex="-1">Neutral <a class="header-anchor" href="#neutral" aria-label="Permalink to &quot;Neutral&quot;">​</a></h3><ul><li><strong><code>validate-data</code> runtime grows from ~3 s to ~3.05 s.</strong> Negligible in the preflight chain.</li><li><strong><code>.husky/pre-push</code> is now 35 lines instead of 25.</strong> Still a single bash script with a single env-var branch.</li></ul><h2 id="audit-findings-folded-in" tabindex="-1">Audit findings folded in <a class="header-anchor" href="#audit-findings-folded-in" aria-label="Permalink to &quot;Audit findings folded in&quot;">​</a></h2><p>At activation time, Layer 1 surfaced 18 orphan IDs across the project. All 18 overlay files are added in the same commit as the validator change so the activation push is clean:</p><table tabindex="0"><thead><tr><th>Registry</th><th>IDs</th></tr></thead><tbody><tr><td><code>fleet/index.json</code> (category <code>constellation</code>)</td><td>starlink, oneweb, iridium-next, kuiper, planet-labs, sentinel-copernicus, landsat, gps-gnss, galileo-gnss, glonass, beidou, goes-noaa, inmarsat, tundra-molniya, o3b-mpower (all 15 from GH #83)</td></tr><tr><td><code>moon-sites.json</code></td><td>luna16, luna21, beresheet (3 from concurrent parallel-agent moon-tier3 work)</td></tr></tbody></table><h2 id="trail" tabindex="-1">Trail <a class="header-anchor" href="#trail" aria-label="Permalink to &quot;Trail&quot;">​</a></h2><ul><li>GH #83 root-cause regression: 2026-05-24, fix in <code>fe8106e50</code> (overlay backfill only — did not prevent recurrence)</li><li>Three-layer policy: commit <code>4df909dac</code> 2026-05-25 — adds Layers 1, 2, 3 + backfills the 18 audit-found orphans</li><li>AGENTS.md &quot;overlay-completeness rule&quot; with full registry table: same commit</li><li>Pre-push hook env-var gate: <code>.husky/pre-push</code> same commit</li></ul><h2 id="future-extensions" tabindex="-1">Future extensions <a class="header-anchor" href="#future-extensions" aria-label="Permalink to &quot;Future extensions&quot;">​</a></h2><ul><li>If a sixth registry following the base + overlay shape lands (likely candidates: a new <code>cislunar-objects.json</code> for the v0.8 NRHO/DRO work, a <code>tianlu-modules.json</code> for a hypothetical Chinese cislunar station), add it to Layer 1&#39;s check list. Cost per new registry: ~10 lines of validator code.</li><li>If the project later adds a stricter &quot;every locale must have every overlay&quot; expectation (e.g. a translation-completeness gate before a release tag), extend Layer 1 from &quot;en-US only&quot; to &quot;all 14 locales&quot; but keep that stricter check behind a release-only env var so daily preflight cost doesn&#39;t grow.</li><li>If Layer 2 turns out to be set by every contributor anyway (suggesting the cost is acceptable as a default), flip the default and let <code>PREFLIGHT_SKIP_SMOKE=1</code> be the opt-out instead.</li></ul>',38)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
